class FlowIsolation final {
    HHOOK activation_=nullptr,visibility_=nullptr;
public:
    FlowIsolation(){activation_=SetWindowsHookEx(WH_CBT,[](int code,WPARAM w,LPARAM l)->LRESULT{return code==HCBT_ACTIVATE||code==HCBT_MINMAX?1:CallNextHookEx(nullptr,code,w,l);},nullptr,GetCurrentThreadId());if(!activation_)throw std::runtime_error("Flow fixture activation guard");visibility_=SetWindowsHookEx(WH_CALLWNDPROC,[](int code,WPARAM w,LPARAM l)->LRESULT{if(code>=0){const auto* message=reinterpret_cast<CWPSTRUCT*>(l);if(message->message==WM_WINDOWPOSCHANGING&&GetAncestor(message->hwnd,GA_ROOT)==message->hwnd){auto* position=reinterpret_cast<WINDOWPOS*>(message->lParam);position->flags=(position->flags&~SWP_SHOWWINDOW)|SWP_NOACTIVATE;}}return CallNextHookEx(nullptr,code,w,l);},nullptr,GetCurrentThreadId());if(!visibility_){UnhookWindowsHookEx(activation_);throw std::runtime_error("Flow fixture visibility guard");}}
    ~FlowIsolation(){UnhookWindowsHookEx(visibility_);UnhookWindowsHookEx(activation_);}
};
sct::core::Image Pixels(int w=1024,int h=640){sct::core::Image image;if(!image.Create(w,h))throw std::runtime_error("Flow fixture pixels");std::fill(image.pixels.begin(),image.pixels.end(),BYTE{255});return image;}
sct::core::DocumentState State(){using namespace sct::core;auto state=Document(Pixels()).State();state.objects={MakeFlowNode(1,{50,60,210,148}),MakeFlowNode(3,{610,200,770,312},1),MakeFlowNode(5,{350,400,510,488},2)};state.objects[0].text=L"Input";state.objects[1].text=L"Ready?";state.objects[2].text=L"Store";return state;}
template<class F>bool Reject(F f){try{f();return false;}catch(const std::exception&){return true;}}
void Seal(std::vector<BYTE>& bytes){uint32_t crc=~0u;for(size_t i=0;i<bytes.size()-4;++i){crc^=bytes[i];for(int b=0;b<8;++b)crc=(crc>>1)^(0xEDB88320u&uint32_t(-int(crc&1)));}crc=~crc;memcpy(bytes.data()+bytes.size()-4,&crc,4);}
